  "2. Elige una dirección": "2. Choose an address",
  "Crea un dominio o subdominio para Nodus. Haz que su DNS apunte a la IP pública del servidor; si la IP cambia, configura DDNS. Caddy obtiene HTTPS, pero no crea el registro DNS.":
    "Create a domain or subdomain for Nodus. Point its DNS to the server public IP; configure DDNS if the IP changes. Caddy obtains HTTPS, but it does not create the DNS record.",
  "3. Despliega el Stack": "3. Deploy the Stack",
  "En Portainer abre Stacks, crea uno nuevo y pega el Stack oficial. Define NODUS_DOMAIN, NODUS_ADMIN_EMAIL y una NODUS_ADMIN_PASSWORD única de al menos 12 caracteres. Las dos credenciales deben configurarse juntas.":
    "In Portainer, open Stacks, create a new one, and paste the official Stack. Set NODUS_DOMAIN, NODUS_ADMIN_EMAIL, and a unique NODUS_ADMIN_PASSWORD of at least 12 characters. Both credential variables must be configured together.",
  "4. Publica HTTPS de forma segura": "4. Publish HTTPS securely",
  "Si no tienes proxy, el Stack con Caddy utiliza los puertos 80 y 443. Si ya usas Caddy o Nginx, despliega solo Nodus Server y dirige el proxy a 127.0.0.1:7443 o nodus-server:7443. Cloudflare Tunnel también puede apuntar a ese destino. Nunca expongas 7443 directamente a Internet.":
    "If you do not have a proxy, the Caddy Stack uses ports 80 and 443. If you already use Caddy or Nginx, deploy only Nodus Server and send proxy traffic to 127.0.0.1:7443 or nodus-server:7443. Cloudflare Tunnel can also target that address. Never expose 7443 directly to the Internet.",
  "5. Inicia sesión": "5. Sign in",
  "Abre https://tu-dominio: el servidor habrá creado o actualizado la cuenta y mostrará directamente el login. Para rotar las credenciales, cambia las variables y vuelve a desplegar. Como alternativa puedes dejar ambas vacías y utilizar /setup con un NODUS_SETUP_TOKEN temporal.":
    "Open https://your-domain: the server will have created or updated the account and will show the login page directly. To rotate credentials, change the variables and redeploy. Alternatively, leave both empty and use /setup with a temporary NODUS_SETUP_TOKEN.",
  "6. Crea usuarios y espacios": "6. Create users and spaces",
  "En la administración web crea un espacio, crea las cuentas lectoras y concede a cada persona únicamente los espacios que debe consultar. El administrador puede restablecer contraseñas temporales.":
    "In web administration, create a space and reader accounts, then grant each person only the spaces they should read. The administrator can reset temporary passwords.",
  "7. Conecta este vault": "7. Connect this vault",
  "En el servidor genera un código para Nodus. Aquí, en Ajustes → Servidor, escribe la dirección HTTPS y ese código de un solo uso. Nodus enviará una copia filtrada y la mantendrá actualizada mientras la aplicación esté abierta.":
    "Generate a Nodus code on the server. Here, under Settings → Server, enter the HTTPS address and that single-use code. Nodus will send a filtered copy and keep it updated while the app is open.",
  "8. Conecta ChatGPT o Claude": "8. Connect ChatGPT or Claude",
