  "9. Mantén el servidor": "9. Maintain the server",
  "Actualiza periódicamente la imagen main, limita el acceso administrativo a Docker o Portainer, protege las variables de entorno y conserva copias probadas del volumen nodus_data. Las credenciales y la base SQLite original no se publican desde el vault.":
    "Update the main image regularly, restrict administrative access to Docker or Portainer, protect environment variables, and keep tested backups of the nodus_data volume. Credentials and the original SQLite database are not published from the vault.",
