  "Sigue estos pasos en orden. No necesitas abrir puertos en el ordenador donde utilizas Nodus Desktop.": "请按顺序执行这些步骤。你无需在使用 Nodus Desktop 的电脑上打开端口。",
  "1. Prepara el equipo": "1. 准备主机",
  "Instala Docker Desktop en Windows o macOS, o Docker Engine en Linux. También puedes usar un VPS y administrar el Stack desde Portainer. El equipo debe permanecer encendido.": "在 Windows 或 macOS 上安装 Docker Desktop，或在 Linux 上安装 Docker Engine。你也可以使用 VPS 并从 Portainer 管理 Stack。主机必须保持开机。",
  "2. Elige una dirección": "2. 选择地址",
  "Crea un dominio o subdominio para Nodus. Haz que su DNS apunte a la IP pública del servidor; si la IP cambia, configura DDNS. Caddy obtiene HTTPS, pero no crea el registro DNS.": "为 Nodus 创建域名或子域名。使其 DNS 指向服务器的公网 IP；如果 IP 发生变化，请配置 DDNS。Caddy 会获取 HTTPS，但不会创建 DNS 记录。",
  "3. Despliega el Stack": "3. 部署 Stack",
  "En Portainer abre Stacks, crea uno nuevo y pega el Stack oficial. Define NODUS_DOMAIN, NODUS_ADMIN_EMAIL y una NODUS_ADMIN_PASSWORD única de al menos 12 caracteres. Las dos credenciales deben configurarse juntas.": "在 Portainer 中打开 Stacks，新建一个并粘贴官方 Stack。定义 NODUS_DOMAIN、NODUS_ADMIN_EMAIL 以及至少 12 个字符的唯一 NODUS_ADMIN_PASSWORD。这两个凭据变量必须一起配置。",
  "4. Publica HTTPS de forma segura": "4. 安全地发布 HTTPS",
  "Si no tienes proxy, el Stack con Caddy utiliza los puertos 80 y 443. Si ya usas Caddy o Nginx, despliega solo Nodus Server y dirige el proxy a 127.0.0.1:7443 o nodus-server:7443. Cloudflare Tunnel también puede apuntar a ese destino. Nunca expongas 7443 directamente a Internet.": "如果你没有代理，带 Caddy 的 Stack 会使用 80 和 443 端口。如果你已使用 Caddy 或 Nginx，请仅部署 Nodus Server，并将代理指向 127.0.0.1:7443 或 nodus-server:7443。Cloudflare Tunnel 也可以指向该目标。切勿将 7443 直接暴露到互联网。",
  "5. Inicia sesión": "5. 登录",
  "Abre https://tu-dominio: el servidor habrá creado o actualizado la cuenta y mostrará directamente el login. Para rotar las credenciales, cambia las variables y vuelve a desplegar. Como alternativa puedes dejar ambas vacías y utilizar /setup con un NODUS_SETUP_TOKEN temporal.": "打开 https://tu-dominio：服务器将已创建或更新账户，并直接显示登录页。要轮换凭据，请修改变量并重新部署。或者，你也可以将两者留空，并使用带临时 NODUS_SETUP_TOKEN 的 /setup。",
  "6. Crea usuarios y espacios": "6. 创建用户和空间",
  "En la administración web crea un espacio, crea las cuentas lectoras y concede a cada persona únicamente los espacios que debe consultar. El administrador puede restablecer contraseñas temporales.": "在 Web 管理中创建一个空间，创建读者账户，并只授予每个人应查阅的空间。管理员可以重置临时密码。",
  "7. Conecta este vault": "7. 连接此资料库",
  "En el servidor genera un código para Nodus. Aquí, en Ajustes → Servidor, escribe la dirección HTTPS y ese código de un solo uso. Nodus enviará una copia filtrada y la mantendrá actualizada mientras la aplicación esté abierta.": "在服务器上为 Nodus 生成一个代码。在此处的「设置 → 服务器」中输入 HTTPS 地址和该一次性代码。只要应用处于打开状态，Nodus 就会发送筛选后的副本并使其保持更新。",
  "8. Conecta ChatGPT o Claude": "8. 连接 ChatGPT 或 Claude",
  "Añade https://tu-dominio/mcp como servidor MCP remoto. El cliente abrirá OAuth: cada persona inicia sesión, autoriza la lectura y solo puede consultar los espacios que tenga asignados.": "将 https://tu-dominio/mcp 添加为远程 MCP 服务器。客户端将打开 OAuth：每个人登录、授权读取，并且只能查阅分配给自己的空间。",
  "9. Mantén el servidor": "9. 维护服务器",
  "Actualiza periódicamente la imagen main, limita el acceso administrativo a Docker o Portainer, protege las variables de entorno y conserva copias probadas del volumen nodus_data. Las credenciales y la base SQLite original no se publican desde el vault.": "定期更新 main 镜像，限制对 Docker 或 Portainer 的管理访问，保护环境变量，并保留 nodus_data 卷的经验证备份。凭据和原始 SQLite 数据库不会从资料库中发布。",
  "Regla de seguridad": "安全规则",
  "Solo el reverse proxy o el túnel debe ser público y siempre con HTTPS. Restringe el acceso a Docker o Portainer, protege las variables de credenciales y no compartas contraseñas por mensajes sin cifrar.": "只有反向代理或隧道应对外公开，且始终使用 HTTPS。限制对 Docker 或 Portainer 的访问，保护凭据变量，不要通过未加密的消息分享密码。",
