  "Publicar biblioteca y documentos": "釋出文獻庫和文件",
  "Publica el catálogo global completo, el Clean Markdown y sus figuras para leerlos sin conexión en Nodus Mobile. Los documentos originales nunca se envían.": "釋出完整的全域性目錄、Clean Markdown 及其插圖，以便在 Nodus Mobile 中離線閱讀。原始文件絕不會發送。",
  "Los estudiantes e investigadores inician sesión por OAuth desde ChatGPT o Claude; solo ven los espacios que el administrador les haya asignado.": "學生和研究人員通過 ChatGPT 或 Claude 的 OAuth 登入；他們只能看到管理員分配給他們的空間。",
  "Cómo funciona": "工作原理",
  "Cada vault se conecta por separado y sigue publicándose en segundo plano aunque estés trabajando en otro vault.": "每個資料庫單獨連線，即使你在另一個資料庫中工作，也會繼續在後臺釋出。",
  "Tu ordenador es quien publica: mantenlo encendido y con Nodus abierto para enviar las novedades.": "釋出的是你的電腦：請保持開機並讓 Nodus 處於開啟狀態以傳送更新。",
  "El servidor Docker sirve la última copia a ChatGPT o Claude aunque tu ordenador esté apagado.": "即使你的電腦已關閉，Docker 伺服器也會向 ChatGPT 或 Claude 提供最新副本。",
  "Vaults conectados": "已連線資料庫",
  "Vault actual": "當前資料庫",
  "En pausa": "已暫停",
  "Cámbiate a este vault para editar su idioma y qué se publica.": "切換到此資料庫以編輯其語言和釋出內容。",
  "Conectar también este vault": "同時連線此資料庫",
  "Instalación del servidor": "伺服器安裝",
  "se ejecuta con Docker en otro equipo o VPS. Puede usar el Caddy incluido o tu Caddy/Nginx existente con un dominio o subdominio y HTTPS. La configuración inicial y la gestión de usuarios se hacen desde el navegador.": "通過 Docker 在另一臺電腦或 VPS 上執行。它可以使用內建的 Caddy，也可以使用你現有的帶域名或子域名及 HTTPS 的 Caddy/Nginx。初始設定和使用者管理在瀏覽器中完成。",
  "Guía de instalación paso a paso": "分步安裝指南",
  "Cómo instalar y conectar Nodus Server": "如何安裝並連線 Nodus Server",
  "Sigue estos pasos en orden. No necesitas abrir puertos en el ordenador donde utilizas Nodus Desktop.": "請按順序執行這些步驟。你無需在使用 Nodus Desktop 的電腦上開啟埠。",
  "1. Prepara el equipo": "1. 準備主機",
  "Instala Docker Desktop en Windows o macOS, o Docker Engine en Linux. También puedes usar un VPS y administrar el Stack desde Portainer. El equipo debe permanecer encendido.": "在 Windows 或 macOS 上安裝 Docker Desktop，或在 Linux 上安裝 Docker Engine。你也可以使用 VPS 並從 Portainer 管理 Stack。主機必須保持開機。",
  "2. Elige una dirección": "2. 選擇地址",
  "Crea un dominio o subdominio para Nodus. Haz que su DNS apunte a la IP pública del servidor; si la IP cambia, configura DDNS. Caddy obtiene HTTPS, pero no crea el registro DNS.": "為 Nodus 建立域名或子域名。使其 DNS 指向伺服器的公網 IP；如果 IP 發生變化，請配置 DDNS。Caddy 會獲取 HTTPS，但不會建立 DNS 記錄。",
  "3. Despliega el Stack": "3. 部署 Stack",
  "En Portainer abre Stacks, crea uno nuevo y pega el Stack oficial. Define NODUS_DOMAIN, NODUS_ADMIN_EMAIL y una NODUS_ADMIN_PASSWORD única de al menos 12 caracteres. Las dos credenciales deben configurarse juntas.": "在 Portainer 中開啟 Stacks，新建一個並貼上官方 Stack。定義 NODUS_DOMAIN、NODUS_ADMIN_EMAIL 以及至少 12 個字元的唯一 NODUS_ADMIN_PASSWORD。這兩個憑據變數必須一起配置。",
  "4. Publica HTTPS de forma segura": "4. 安全地釋出 HTTPS",
  "Si no tienes proxy, el Stack con Caddy utiliza los puertos 80 y 443. Si ya usas Caddy o Nginx, despliega solo Nodus Server y dirige el proxy a 127.0.0.1:7443 o nodus-server:7443. Cloudflare Tunnel también puede apuntar a ese destino. Nunca expongas 7443 directamente a Internet.": "如果你沒有代理，帶 Caddy 的 Stack 會使用 80 和 443 埠。如果你已使用 Caddy 或 Nginx，請僅部署 Nodus Server，並將代理指向 127.0.0.1:7443 或 nodus-server:7443。Cloudflare Tunnel 也可以指向該目標。切勿將 7443 直接暴露到網際網路。",
  "5. Inicia sesión": "5. 登入",
  "Abre https://tu-dominio: el servidor habrá creado o actualizado la cuenta y mostrará directamente el login. Para rotar las credenciales, cambia las variables y vuelve a desplegar. Como alternativa puedes dejar ambas vacías y utilizar /setup con un NODUS_SETUP_TOKEN temporal.": "開啟 https://tu-dominio：伺服器將已建立或更新帳戶，並直接顯示登入頁。要輪換憑據，請修改變數並重新部署。或者，你也可以將兩者留空，並使用帶臨時 NODUS_SETUP_TOKEN 的 /setup。",
  "6. Crea usuarios y espacios": "6. 建立使用者和空間",
  "En la administración web crea un espacio, crea las cuentas lectoras y concede a cada persona únicamente los espacios que debe consultar. El administrador puede restablecer contraseñas temporales.": "在 Web 管理中建立一個空間，建立讀者帳戶，並只授予每個人應查閱的空間。管理員可以重置臨時密碼。",
  "7. Conecta este vault": "7. 連線此資料庫",
  "En el servidor genera un código para Nodus. Aquí, en Ajustes → Servidor, escribe la dirección HTTPS y ese código de un solo uso. Nodus enviará una copia filtrada y la mantendrá actualizada mientras la aplicación esté abierta.": "在伺服器上為 Nodus 生成一個程式碼。在此處的「設定 → 伺服器」中輸入 HTTPS 地址和該一次性程式碼。只要應用處於開啟狀態，Nodus 就會發送篩選後的副本並使其保持更新。",
  "8. Conecta ChatGPT o Claude": "8. 連線 ChatGPT 或 Claude",
  "Añade https://tu-dominio/mcp como servidor MCP remoto. El cliente abrirá OAuth: cada persona inicia sesión, autoriza la lectura y solo puede consultar los espacios que tenga asignados.": "將 https://tu-dominio/mcp 新增為遠端 MCP 伺服器。客戶端將開啟 OAuth：每個人登入、授權讀取，並且只能查閱分配給自己的空間。",
  "9. Mantén el servidor": "9. 維護伺服器",
  "Actualiza periódicamente la imagen main, limita el acceso administrativo a Docker o Portainer, protege las variables de entorno y conserva copias probadas del volumen nodus_data. Las credenciales y la base SQLite original no se publican desde el vault.": "定期更新 main 映象，限制對 Docker 或 Portainer 的管理訪問，保護環境變數，並保留 nodus_data 卷的經驗證備份。憑據和原始 SQLite 資料庫不會從資料庫中釋出。",
  "Regla de seguridad": "安全規則",
  "Solo el reverse proxy o el túnel debe ser público y siempre con HTTPS. Restringe el acceso a Docker o Portainer, protege las variables de credenciales y no compartas contraseñas por mensajes sin cifrar.": "只有反向代理或隧道應對外公開，且始終使用 HTTPS。限制對 Docker 或 Portainer 的訪問，保護憑據變數，不要通過未加密的訊息分享密碼。",
