    "Cómo funciona": "Como funciona",
    "Cada vault se conecta por separado y sigue publicándose en segundo plano aunque estés trabajando en otro vault.":
      "Cada cofre se conecta separadamente e continua publicando em segundo plano mesmo enquanto você trabalha em outro cofre.",
    "Tu ordenador es quien publica: mantenlo encendido y con Nodus abierto para enviar las novedades.":
      "É o seu computador que publica: mantenha-o ligado e com o Nodus aberto para enviar as novidades.",
    "El servidor Docker sirve la última copia a ChatGPT o Claude aunque tu ordenador esté apagado.":
      "O servidor Docker serve a última cópia ao ChatGPT ou Claude mesmo com o computador desligado.",
    "Vaults conectados": "Cofres conectados",
    "Vault actual": "Cofre atual",
    "En pausa": "Em pausa",
    "Cámbiate a este vault para editar su idioma y qué se publica.":
      "Mude para este cofre para editar o idioma dele e o que é publicado.",
    "Conectar también este vault": "Conectar também este cofre",
    "Conectado a": "Conectado a",
    "Vault publicado correctamente.": "Cofre publicado com sucesso.",
    "Desconectar Nodus Server": "Desconectar o Nodus Server",
    "Nodus dejará de publicar este vault. La última copia seguirá en el servidor hasta que su administrador la elimine.":
      "O Nodus deixará de publicar este cofre. A última cópia permanecerá no servidor até que o administrador a exclua.",
    "Servidor desconectado.": "Servidor desconectado.",
    "Idioma de la interfaz del servidor": "Idioma da interface do servidor",
    "Cambia la administración web y las pantallas de acceso para todos los usuarios. El idioma inicial es inglés.":
      "Altera a administração web e as telas de login para todos os usuários. O idioma inicial é inglês.",
    "Idioma del servidor actualizado.": "Idioma do servidor atualizado.",
    "Vault compartido, siempre actualizado":
      "Um cofre compartilhado, sempre atualizado",
    "Nodus publica una copia lógica y filtrada de este vault mediante HTTPS saliente. No abre ningún puerto en tu ordenador y no comparte listener, puerto ni token con el MCP local.":
      "O Nodus publica uma cópia lógica e filtrada deste cofre por HTTPS de saída. Ele não abre nenhuma porta no computador nem compartilha listener, porta ou token com o MCP local.",
    "Conectar este vault": "Conectar este cofre",
    "Entra en la administración web del servidor, crea un espacio y genera un código de conexión de un solo uso.":
      "Abra a administração web do servidor, crie um espaço e gere um código de conexão de uso único.",
    "Dirección del servidor": "Endereço do servidor",
