    "Servidor desconectado.": "Server disconnesso.",
    "Idioma de la interfaz del servidor": "Lingua dell'interfaccia del server",
    "Cambia la administración web y las pantallas de acceso para todos los usuarios. El idioma inicial es inglés.":
      "Cambia l'amministrazione web e le schermate di accesso per tutti gli utenti. La lingua iniziale è l'inglese.",
    "Idioma del servidor actualizado.": "Lingua del server aggiornata.",
    "Vault compartido, siempre actualizado":
      "Un vault condiviso, sempre aggiornato",
    "Nodus publica una copia lógica y filtrada de este vault mediante HTTPS saliente. No abre ningún puerto en tu ordenador y no comparte listener, puerto ni token con el MCP local.":
      "Nodus pubblica una copia logica e filtrata di questo vault tramite HTTPS in uscita. Non apre porte sul computer e non condivide listener, porta o token con MCP locale.",
    "Conectar este vault": "Connetti questo vault",
    "Entra en la administración web del servidor, crea un espacio y genera un código de conexión de un solo uso.":
      "Apri l'amministrazione web del server, crea uno spazio e genera un codice di connessione monouso.",
    "Dirección del servidor": "Indirizzo del server",
